import React, { useState } from 'react';
import { CardElement, useStripe, useElements } from '@stripe/react-stripe-js';

function PaymentModal({ booking, amount, onSuccess, onCancel }) {
  const stripe = useStripe();
  const elements = useElements();
  const [paymentMethod, setPaymentMethod] = useState('card');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const token = localStorage.getItem('token');

  const handleCardPayment = async (e) => {
    e.preventDefault();

    if (!stripe || !elements) {
      setError('Stripe not initialized. Please try again.');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Create payment intent on backend
      console.log('Creating payment intent for booking:', booking._id);

      const intentRes = await fetch('http://localhost:5000/api/payments/create-intent', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          bookingId: booking._id,
          amount: amount
        })
      });

      const intentData = await intentRes.json();
      console.log('Payment intent response:', intentData);

      if (!intentData.success) {
        throw new Error(intentData.error || 'Failed to create payment');
      }

      // Confirm payment with Stripe
      const { error: confirmError, paymentIntent } = await stripe.confirmCardPayment(
        intentData.clientSecret,
        {
          payment_method: {
            card: elements.getElement(CardElement),
            billing_details: {
              name: booking.customerName || 'Customer',
            },
          },
        }
      );

      if (confirmError) {
        console.error('Stripe confirm error:', confirmError);
        setError(confirmError.message);
        setLoading(false);
        return;
      }

      if (paymentIntent.status === 'succeeded') {
        // Confirm with backend
        const confirmRes = await fetch('http://localhost:5000/api/payments/confirm', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`
          },
          body: JSON.stringify({
            paymentIntentId: paymentIntent.id,
            bookingId: booking._id
          })
        });

        const confirmData = await confirmRes.json();

        if (confirmData.success) {
          onSuccess();
        } else {
          setError(confirmData.error || 'Payment confirmation failed');
        }
      }
    } catch (err) {
      console.error('Payment error:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleCashPayment = async () => {
    setLoading(true);
    setError('');

    try {
      const res = await fetch('http://localhost:5000/api/payments/cash', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          bookingId: booking._id,
          amount: amount
        })
      });

      const data = await res.json();

      if (data.success) {
        onSuccess();
      } else {
        setError(data.error || 'Failed to process cash payment');
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const cardElementOptions = {
    style: {
      base: {
        fontSize: '16px',
        color: '#1f2937',
        fontFamily: 'monospace',
        '::placeholder': { color: '#9ca3af' }
      },
      invalid: { color: '#ef4444' }
    }
  };

  return (
    <div style={styles.modal}>
      <div style={styles.modalContent}>
        <h2>💳 Payment Details</h2>
        <p><strong>Service:</strong> {booking.serviceName}</p>
        <p><strong>Amount:</strong> ${amount}</p>
        <p><strong>Platform Fee (15%):</strong> ${(amount * 0.15).toFixed(2)}</p>
        <p><strong>You Pay:</strong> ${amount}</p>

        <div style={styles.paymentMethods}>
          <button style={{...styles.methodBtn, ...(paymentMethod === 'card' ? styles.methodActive : {})}} onClick={() => setPaymentMethod('card')}>💳 Credit Card</button>
          <button style={{...styles.methodBtn, ...(paymentMethod === 'cash' ? styles.methodActive : {})}} onClick={() => setPaymentMethod('cash')}>💵 Pay at Shop</button>
        </div>

        {paymentMethod === 'card' && (
          <form onSubmit={handleCardPayment}>
            <div style={styles.cardElement}>
              <p>Card Details</p>
              <CardElement options={cardElementOptions} />
              <p style={styles.testCardInfo}>Test card: 4242 4242 4242 4242 | Any future date | Any CVC</p>
            </div>
            {error && <div style={styles.error}>{error}</div>}
            <div style={styles.modalActions}>
              <button type="submit" style={styles.submitBtn} disabled={loading || !stripe}>
                {loading ? 'Processing...' : `Pay $${amount}`}
              </button>
              <button type="button" style={styles.cancelBtn} onClick={onCancel}>Cancel</button>
            </div>
          </form>
        )}

        {paymentMethod === 'cash' && (
          <div>
            <div style={styles.cashInfo}>
              <p>✅ You will pay ${amount} at the service center</p>
              <p>Booking will be confirmed immediately</p>
            </div>
            {error && <div style={styles.error}>{error}</div>}
            <div style={styles.modalActions}>
              <button style={styles.submitBtn} onClick={handleCashPayment} disabled={loading}>
                {loading ? 'Processing...' : 'Confirm Booking (Pay at Shop)'}
              </button>
              <button style={styles.cancelBtn} onClick={onCancel}>Cancel</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

const styles = {
  modal: { position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 },
  modalContent: { backgroundColor: 'white', padding: '30px', borderRadius: '10px', maxWidth: '500px', width: '90%' },
  paymentMethods: { display: 'flex', gap: '10px', margin: '20px 0' },
  methodBtn: { flex: 1, padding: '10px', border: '1px solid #d1d5db', background: 'white', borderRadius: '6px', cursor: 'pointer' },
  methodActive: { borderColor: '#10b981', background: '#d1fae5', color: '#065f46' },
  cardElement: { border: '1px solid #d1d5db', padding: '15px', borderRadius: '6px', marginBottom: '20px' },
  testCardInfo: { fontSize: '11px', color: '#6b7280', marginTop: '8px' },
  cashInfo: { backgroundColor: '#d1fae5', padding: '15px', borderRadius: '6px', marginBottom: '20px' },
  error: { backgroundColor: '#fee2e2', color: '#dc2626', padding: '10px', borderRadius: '6px', marginBottom: '20px' },
  modalActions: { display: 'flex', gap: '10px', marginTop: '20px' },
  submitBtn: { flex: 1, backgroundColor: '#10b981', color: 'white', border: 'none', padding: '12px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' },
  cancelBtn: { flex: 1, backgroundColor: '#6b7280', color: 'white', border: 'none', padding: '12px', borderRadius: '6px', cursor: 'pointer' }
};

export default PaymentModal;
